Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

int n;
int S;
int cnt[250], id[250];
int f[10][250];
vector<int> vec[10];
map<pair<int, long long>, int> mp;

int power(int base, int exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = (long long)result * base % MOD;
        base = (long long)base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int DP(int x, long long state) {
    if (state == 0) return 0;
    if (x == n) return 1;
    auto key = make_pair(x, state);
    if (mp.count(key)) return mp[key];

    S++;
    int answer = 0;
    for (int j = 1; j <= (1 << n) - 1; ++j) {
        long long next_state = 0;
        for (size_t k = 0; k < vec[x].size(); ++k) {
            if (!(state & (1LL << k))) continue;
            int las = vec[x][k];
            for (int l = 0; l < n; ++l) {
                if ((j & (1 << l)) && !(las & (1 << l))) {
                    next_state |= 1LL << id[las | (1 << l)];
                }
            }
        }
        answer = (answer + (long long)f[x][j] * DP(x + 1, next_state)) % MOD;
    }
    mp[key] = answer;
    return answer;
}

int main() {
    cin >> n;
    int inv100 = power(100, MOD - 2);
    for (int i = 0; i < n; ++i) {
        f[i][0] = 1;
        for (int j = 0; j < n; ++j) {
            int P;
            cin >> P;
            int p1 = (long long)P * inv100 % MOD;
            int p0 = (MOD + 1 - p1) % MOD;
            for (int k = 0; k < (1 << j); ++k) {
                f[i][k | (1 << j)] = (long long)f[i][k] * p1 % MOD;
                f[i][k] = (long long)f[i][k] * p0 % MOD;
            }
        }
    }
    for (int i = 0; i < (1 << n); ++i) {
        cnt[i] = __builtin_popcount(i);
    }
    for (int i = 0; i < (1 << n); ++i) {
        vec[cnt[i]].push_back(i);
        id[i] = (int)vec[cnt[i]].size() - 1;
    }
    cout << DP(0, 1LL) << "\n";
    return 0;
}
